
.battle {
  margin: 10px 14px 0;
  padding: 10px 12px;
  border-radius: var(--radius);
  border: 1px solid var(--c-accent-soft);
  background: linear-gradient(120deg, rgba(224, 82, 94, 0.08), rgba(224, 82, 94, 0.02) 55%);
}

.battle-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.battle-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--c-accent);
}

.battle-tag {
  font-size: 11px;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--c-accent-soft);
  color: var(--c-accent);
}

.hp-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.hp-label {
  font-size: 11px;
  color: var(--c-text-dim);
  width: 52px;
}

.hp-track {
  flex: 1;
  height: 10px;
  border-radius: 5px;
  background: #ffffff12;
  overflow: hidden;
}

.hp-fill {
  height: 100%;
  border-radius: 5px;
  transition: width 0.4s ease;
}

.hp-num {
  font-size: 12px;
  font-weight: 600;
  min-width: 52px;
  text-align: right;
}

.battle-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin-top: 8px;
  font-size: 12px;
  color: var(--c-text-muted);
}

.battle-state {
  margin-top: 8px;
  padding: 6px 10px;
  border-radius: 7px;
  font-size: 12px;
  background: #ffffff08;
  color: var(--c-text-muted);
}

.battle-state.进行中 {
  color: var(--c-accent);
  background: var(--c-accent-soft);
}
