
.roster-head {
  display: flex;
  justify-content: space-between;
  color: var(--c-text-dim);
  font-size: 11px;
  letter-spacing: 1px;
  margin-bottom: 8px;
}

.roster-count {
  color: var(--c-accent);
}

.roster-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(158px, 1fr));
  gap: 8px;
}

.roster-card {
  padding: 8px 10px;
  border-radius: 9px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  cursor: pointer;
  transition: all 0.15s ease;
}

.roster-card:hover {
  border-color: var(--c-accent-soft);
  transform: translateY(-1px);
}

.roster-card.captured {
  border-color: var(--c-accent-soft);
  background: linear-gradient(150deg, rgba(224, 82, 94, 0.1), var(--c-surface-raised) 60%);
}

.roster-card.fighting {
  border-color: var(--c-gold);
  box-shadow: 0 0 0 1px var(--c-gold-soft);
}

.rc-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 6px;
}

.rc-name {
  font-weight: 700;
  font-size: 12.5px;
  color: var(--c-text);
}

.rc-role {
  font-size: 10px;
  color: var(--c-text-dim);
  white-space: nowrap;
}

.rc-tags {
  display: flex;
  gap: 4px;
  margin-top: 4px;
  min-height: 14px;
}

.rc-tag {
  font-size: 10px;
  padding: 0 5px;
  border-radius: 4px;
  background: #ffffff0d;
  color: var(--c-text-muted);
}

.rc-hp {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
}

.rc-track {
  flex: 1;
  height: 5px;
  border-radius: 3px;
  background: #ffffff12;
  overflow: hidden;
}

.rc-fill {
  height: 100%;
  border-radius: 3px;
}

.rc-num {
  font-size: 10.5px;
  color: var(--c-text-muted);
  min-width: 20px;
  text-align: right;
}

.rc-sub {
  margin-top: 5px;
  font-size: 10.5px;
  color: var(--c-text-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
