
.sched-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 10px;
  border-radius: 7px;
  margin-bottom: 4px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
}

.sched-time {
  min-width: 56px;
  font-weight: 700;
  color: var(--c-gold);
  font-size: 12px;
}

.sched-p {
  flex: 1;
  font-size: 12px;
  color: var(--c-text);
}

.sched-p.done {
  color: var(--c-text-dim);
}

.sched-result {
  font-size: 12px;
  color: var(--c-text-muted);
}

.sched-result.win {
  color: var(--c-success);
}

.sched-result.lose {
  color: var(--c-danger);
}

.sched-result.refuse {
  color: var(--c-warning);
}

.sched-empty {
  color: var(--c-text-dim);
  font-size: 12px;
  padding: 8px;
}
