
.detail {
  margin-top: 6px;
}

.detail-head {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--c-border);
  margin-bottom: 10px;
}

.detail-back {
  cursor: pointer;
  color: var(--c-text-muted);
  font-size: 12px;
}

.detail-back:hover {
  color: var(--c-accent);
}

.detail-name {
  font-size: 16px;
  font-weight: 700;
}

.detail-role {
  font-size: 12px;
  color: var(--c-text-muted);
}

.detail-tag {
  font-size: 11px;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--c-accent-soft);
  color: var(--c-accent);
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 8px;
  margin-bottom: 8px;
}

.d-sec {
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  margin-bottom: 8px;
}

.d-sec-title {
  font-size: 11px;
  color: var(--c-text-dim);
  letter-spacing: 2px;
  margin-bottom: 6px;
}

.nsfw-tag {
  font-size: 9px;
  color: var(--c-accent);
  border: 1px solid var(--c-accent-soft);
  border-radius: 4px;
  padding: 0 4px;
  vertical-align: 1px;
}

.d-line {
  display: flex;
  gap: 8px;
  font-size: 12px;
  padding: 2px 0;
}

.d-line span {
  color: var(--c-text-dim);
  min-width: 56px;
  flex-shrink: 0;
}

.d-line b {
  font-weight: 500;
  color: var(--c-text);
  word-break: break-all;
}

.d-text {
  font-size: 12px;
  color: var(--c-text-muted);
  line-height: 1.6;
  margin-bottom: 4px;
}

.psy-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
}

.psy {
  font-size: 12px;
  color: var(--c-text-muted);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.psy i {
  display: inline-block;
  width: 56px;
  height: 5px;
  border-radius: 3px;
  background: #ffffff12;
  overflow: hidden;
}

.body-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 6px;
}

.body-card {
  padding: 6px 8px;
  border-radius: 7px;
  background: #ffffff07;
  border: 1px solid var(--c-border);
}

.bc-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--c-powder);
  margin-bottom: 3px;
}

.bc-line {
  font-size: 11px;
  color: var(--c-text-muted);
  margin: 2px 0;
}

.bc-line i {
  display: inline-block;
  width: 44px;
  height: 4px;
  border-radius: 2px;
  background: #ffffff12;
  overflow: hidden;
  vertical-align: middle;
  margin-right: 4px;
}
