
.skill-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 8px;
}

.skill-card {
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
}

.sk-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.sk-name {
  font-weight: 700;
  font-size: 13px;
  color: var(--c-gold);
}

.sk-lv {
  font-size: 11px;
  color: var(--c-text-muted);
}

.sk-exp {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 6px 0;
  font-size: 10.5px;
  color: var(--c-text-dim);
}

.sk-track {
  flex: 1;
  height: 5px;
  border-radius: 3px;
  background: #ffffff12;
  overflow: hidden;
}

.sk-fill {
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--c-gold), #e8c77a);
}

.sk-desc {
  font-size: 11px;
  color: var(--c-text-muted);
  line-height: 1.55;
}
